class Registered:
    registry: dict[str, type] = {}

    def __init_subclass__(cls, **kwargs):      # PEP 487 hook
        super().__init_subclass__(**kwargs)
        Registered.registry[cls.__name__] = cls

class Money(Registered):
    def __init__(self, cents: int) -> None:
        self.cents = cents
